// Generated by vibelang from infra/Postgres.ts; the migrate flow writes it again with each batch.
// Postgres in production: one Neon project. infra/ChatDatabase.ts migrates it and puts Hyperdrive in front of it;
// Electric's container (infra/ElectricGateway.ts) replicates from it. Under `alchemy dev` it doesn't exist: the
// compose Postgres (`pnpm db:up`) stands in.
import * as Neon from "@alchemy.run/neon";
import * as Alchemy from "alchemy";
import * as Output from "alchemy/Output";
import { Config, Effect, Option, Redacted, Schema } from "effect";
import { FetchHttpClient, HttpClient, HttpClientRequest, HttpClientResponse } from "effect/http";
import { neonConnectionUri } from "../ops/database/Connection.js";
/** The most restore history Neon's Free plan allows, in seconds: six hours. */
export const HISTORY_RETENTION_SECONDS = 21_600;
/**
 * The production database: Postgres 17 with logical replication on, which Electric's replication needs. Its region and
 * Postgres version can't change after creation, so they are fixed here rather than configured. It is created in the
 * Neon organization `NEON_ORG_ID`, which a personal API key needs and an organization API key implies.
 * `alchemy destroy` keeps it: the conversation outlives any deploy.
 */
export const Postgres = Neon.Project("ChatPostgres", Effect.gen(function* () {
    const orgId = yield* Config.option(Config.String("NEON_ORG_ID"));
    return {
        region: "aws-us-east-1",
        pgVersion: 17,
        enableLogicalReplication: true,
        // Six hours of restore history. Alchemy's default is a day, which Neon's Free plan refuses
        // ("requested history retention seconds exceeds allowed maximum", max 21600). Raise it with the plan.
        historyRetentionSeconds: HISTORY_RETENTION_SECONDS,
        ...(Option.isSome(orgId) ? { orgId: orgId.value } : {})
    };
}).pipe(Effect.orDie)).pipe(Alchemy.RemovalPolicy.retain());
/**
 * Electric's direct (non-pooled) URI, as a secret. Its parser does not take channel_binding.
 */
export const directUrl = (postgres) => Output.map(postgres.connectionUri, (uri) => {
    const url = new URL(uri);
    url.searchParams.delete("channel_binding");
    return Redacted.make(url.toString());
});
/** Deployment migrations share the operator's Neon normalization and explicit verify-full boundary. */
export const migrationUrl = (postgres) => Output.map(postgres.connectionUri, neonConnectionUri);
const Endpoint = Schema.Struct({
    id: Schema.String,
    type: Schema.String,
    branch_id: Schema.String,
    autoscaling_limit_min_cu: Schema.Number,
    autoscaling_limit_max_cu: Schema.Number
});
const Endpoints = Schema.Struct({ endpoints: Schema.Array(Endpoint) });
/**
 * Sets the autoscaling range of the project's read-write compute on its default branch through Neon's API, with the
 * deploy's `NEON_API_KEY`: Alchemy's `Neon.Project` declares no compute size. It runs during a deploy whose range or
 * project changed; Neon restarts the compute to apply a new range, which drops open connections for about a second. It returns
 * the compute it set. A range already set is left alone.
 */
export const Compute = Alchemy.Action("ChatCompute", (input) => Effect.gen(function* () {
    const key = yield* Config.Redacted("NEON_API_KEY");
    const neon = (yield* HttpClient.HttpClient).pipe(HttpClient.mapRequest((request) => request.pipe(HttpClientRequest.prependUrl(`https://console.neon.tech/api/v2/projects/${input.projectId}`), HttpClientRequest.bearerToken(Redacted.value(key)), HttpClientRequest.acceptJson)), HttpClient.filterStatusOk);
    const { endpoints } = yield* neon.execute(HttpClientRequest.get("/endpoints")).pipe(Effect.flatMap(HttpClientResponse.schemaBodyJson(Endpoints)));
    const compute = endpoints.find((endpoint) => endpoint.type === "read_write" && endpoint.branch_id === input.branchId);
    if (compute === undefined) {
        return yield* Effect.die(new Error("ChatCompute: the default branch has no read-write compute"));
    }
    const result = { endpointId: compute.id, minCu: input.minCu, maxCu: input.maxCu };
    // Neon restarts the compute on any update, so a range already set is left alone.
    if (compute.autoscaling_limit_min_cu === input.minCu && compute.autoscaling_limit_max_cu === input.maxCu) {
        return result;
    }
    yield* neon.execute(HttpClientRequest.patch(`/endpoints/${compute.id}`).pipe(HttpClientRequest.bodyJsonUnsafe({
        endpoint: { autoscaling_limit_min_cu: input.minCu, autoscaling_limit_max_cu: input.maxCu }
    })));
    return result;
}).pipe(Effect.provide(FetchHttpClient.layer), Effect.orDie));
